package java.util;
public abstract class EnumSet<E extends Enum<E>> extends AbstractSet<E> implements Cloneable,java.io.Serializable {final Class<E> type;final E[] universe;EnumSet(Class<E> type){this.type=type;universe=type.getEnumConstants();if(universe==null)throw new ClassCastException();}public static <E extends Enum<E>> EnumSet<E> noneOf(Class<E> t){return new Regular<E>(t);}public static <E extends Enum<E>> EnumSet<E> allOf(Class<E> t){EnumSet<E> s=noneOf(t);for(E e:s.universe)s.add(e);return s;}public static <E extends Enum<E>> EnumSet<E> copyOf(EnumSet<E> s){EnumSet<E> n=noneOf(s.type);n.addAll(s);return n;}public static <E extends Enum<E>> EnumSet<E> copyOf(Collection<E> c){if(c instanceof EnumSet)return copyOf((EnumSet<E>)c);if(c.isEmpty())throw new IllegalArgumentException("Collection is empty");EnumSet<E> s=noneOf(c.iterator().next().getDeclaringClass());s.addAll(c);return s;}public static <E extends Enum<E>> EnumSet<E> complementOf(EnumSet<E> s){EnumSet<E> n=allOf(s.type);n.removeAll(s);return n;}public static <E extends Enum<E>> EnumSet<E> of(E first,E... rest){EnumSet<E> s=noneOf(first.getDeclaringClass());s.add(first);for(E e:rest)s.add(e);return s;}public static <E extends Enum<E>> EnumSet<E> of(E e){return of(e,(E[])java.lang.reflect.Array.newInstance(e.getDeclaringClass(),0));}public static <E extends Enum<E>> EnumSet<E> of(E a,E b){EnumSet<E> s=of(a);s.add(b);return s;}public static <E extends Enum<E>> EnumSet<E> of(E a,E b,E c){EnumSet<E> s=of(a,b);s.add(c);return s;}public static <E extends Enum<E>> EnumSet<E> of(E a,E b,E c,E d){EnumSet<E> s=of(a,b,c);s.add(d);return s;}public static <E extends Enum<E>> EnumSet<E> of(E a,E b,E c,E d,E e){EnumSet<E> s=of(a,b,c,d);s.add(e);return s;}public static <E extends Enum<E>> EnumSet<E> range(E from,E to){if(from.compareTo(to)>0)throw new IllegalArgumentException();EnumSet<E> s=noneOf(from.getDeclaringClass());if(from.getDeclaringClass()!=to.getDeclaringClass())throw new ClassCastException();for(int i=from.ordinal();i<=to.ordinal();i++)s.add(s.universe[i]);return s;}public EnumSet<E> clone(){return copyOf(this);}private static class Regular<E extends Enum<E>> extends EnumSet<E>{final boolean[] bits;int count;Regular(Class<E> t){super(t);bits=new boolean[universe.length];}public int size(){return count;}public boolean contains(Object x){return x instanceof Enum&&((Enum)x).getDeclaringClass()==type&&bits[((Enum)x).ordinal()];}public boolean add(E e){if(e==null)throw new NullPointerException();if(e.getDeclaringClass()!=type)throw new ClassCastException();int i=e.ordinal();if(bits[i])return false;bits[i]=true;count++;return true;}public boolean remove(Object e){if(!contains(e))return false;bits[((Enum)e).ordinal()]=false;count--;return true;}public Iterator<E> iterator(){return new Iterator<E>(){int i,last=-1;public boolean hasNext(){while(i<bits.length&&!bits[i])i++;return i<bits.length;}public E next(){if(!hasNext())throw new NoSuchElementException();last=i;return universe[i++];}public void remove(){if(last<0)throw new IllegalStateException();if(bits[last]){bits[last]=false;count--;}last=-1;}};}}}
